{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.00) to correct for overconfidence.",
    "Reduce forecast magnitude by 5-10% if recent history shows persistent underperformance (e.g., model consistently overestimates by >10% over 5+ days).",
    "Apply mean reversion bias: if forecast is >15% above recent 7-day average, reduce by 10-15% to align with historical volatility.",
    "Correct for lagged spikes: if true outcome spikes after a forecast peak, reduce subsequent forecasts by 5-10% to avoid overshoot.",
    "Increase forecast sensitivity to sentiment: if sentiment > 0.25, adjust upward by 3-5% to reflect bullish momentum; if sentiment < -0.25, adjust downward by 3-5% to reflect bearish pressure.",
    "Avoid overreacting to short-term volatility: if true outcome deviates >15% from forecast within 3 days, apply a smoothing filter to reduce noise in next forecast."
  ]
}
